import { get, handleApiError, post } from '@helpers/httpClient';

import { mapBackProductStatToFront, mapBackProductToFront } from '../@mappers/products.mapper';
import {
  IProductAddDTO,
  IProductDTO,
  IProductStatDTO,
  IProductUpdateDTO,
} from '../@types/products.backTypes';

export const getAllProducts = async () => {
  const res = await get<any, IProductDTO[]>('/ajax/recipes/products_list.php').then<IProductDTO[]>(
    handleApiError,
  );
  return res.map(mapBackProductToFront);
};

export const getOneProduct = async (id: number) => {
  const res = await get('/ajax/recipes/product_one.php', {
    id,
  }).then<IProductDTO>(handleApiError);
  return mapBackProductToFront(res);
};

export const getOneProductStat = async (id: number) => {
  const res = await get('/ajax/recipes/product_one_stat.php', {
    id,
  }).then<IProductStatDTO>(handleApiError);
  return mapBackProductStatToFront(res);
};

export const addProduct = async (data: IProductAddDTO) => {
  const res = await post<{ id: number }, IProductAddDTO>(
    '/ajax/recipes/product_add_or_edit.php',
    data,
  ).then<{ id: number }>(handleApiError);
  return res.id;
};

export const updateProduct = async (data: IProductUpdateDTO) => {
  const res = await post<{ success: boolean }, IProductUpdateDTO>(
    '/ajax/recipes/product_add_or_edit.php',
    data,
  ).then<{ success: boolean }>(handleApiError);
  return res.success;
};
